-- [TSMod] Cut battle in the story-battle picker (mods/cut_battles, generated by make_lua.py). Everything below only
-- applies when the battle was started from our picker row (QUEST_INFO_TSMOD_CUT_FREDERICA); the cut script is otherwise unreachable.
local TSMOD_CUT_QUEST = "QUEST_INFO_TSMOD_CUT_FREDERICA"
local function tsmod_cut_log(...)
  if TSLOG ~= nil then pcall(TSLOG, "cut", ...) end
end
local function tsmod_cut_active()
  local ok, id = pcall(GetCurrentQuestInfoId)
  return ok and id == TSMOD_CUT_QUEST, id
end
-- Lap like the shipped replays: 1 = first playthrough, 2 = second, 3 = third or later.
local function tsmod_cut_lap()
  local ok, n = pcall(GetSysGlobal, SysGlobal.GAME_RESULT_COUNT)
  if not ok or n == nil or n <= 0 then return 1 elseif n == 1 then return 2 end
  return 3
end
local function tsmod_cut_lv(base, add)
  local v = base + add
  if v > 50 then v = 50 end
  return v
end
local function tsmod_cut_drop(unit, drop)
  local ok, err = pcall(ChangeDropItemGopId, unit, drop)
  tsmod_cut_log("drop", unit, drop, ok, err)
end
-- Spawn one enemy the way the shipped replays do (BattleUnitSpawnData.SpawnBattleEnemy), logging each step.
local function tsmod_cut_spawn(name, master, param, x, y, dir, lv, wlv)
  tsmod_cut_log("spawn", name, master, param, x, y, "lv", lv, "wlv", wlv)
  SpawnUnit(name, master, param, x, y, dir, 0, 0)
  tsmod_cut_log(" spawned", name)
  LevelUpToTargetLevel(name, lv)
  if wlv ~= nil then
    LevelUpWeaponOnMapUnit(name, wlv)
  end
end
-- Log the battle-setup stages (wraps whatever the script defined).
local function tsmod_cut_trace(cls, fname)
  local f = cls[fname]
  if type(f) ~= "function" then return end
  cls[fname] = function(self, ...)
    tsmod_cut_log("begin", fname)
    local r = {f(self, ...)}
    tsmod_cut_log("end", fname)
    return unpack(r)
  end
end

local tsmod_cut_on, tsmod_cut_qid = tsmod_cut_active()
tsmod_cut_log("script ms17r_x36_battle_01 loaded, quest", tsmod_cut_qid, "ours", tsmod_cut_on)
if tsmod_cut_on then
  BattleTemplateInstance:OverrideSetting({
    BattleFieldTextId = "TEXT_COMMON_BATTLE_UI_BATTLE_NAME_TSMOD_CUT_FREDERICA",
    VictoryRequirementText = "TEXT_COMMON_BATTLE_UI_VICTORY_CONDITION_TSMOD_CUT_FREDERICA",
    MapCfgGopId = "BATTLE_MAPCFG_MS15_X30"
  })
  pcall(function() BattleSetupTemplateInstance:OverrideSetting({MapCfgGopId = "BATTLE_MAPCFG_MS15_X30"}) end)
  -- No debug level-ups or placeholder dialogs from development builds.
  function ClassBattleBase:DebugChangeUnitMasterParameters_Implementation()
  end
  if CallUnitAIFunc ~= nil then
    g_ActiveAIUnitFunction = CallUnitAIFunc
  end
  -- Party units must be spawned under their unit master id (see make_lua.py); map the draft's short name.
  local TSMOD_CUT_NAME = {["P004"] = "UNIT_MASTER_CH_P004"}
  local tsmod_cut_talk = TalkTextWithCamera
  function TalkTextWithCamera(actorName, quote_list)
    return tsmod_cut_talk(TSMOD_CUT_NAME[actorName] or actorName, quote_list)
  end
  local tsmod_cut_ai = ChangeAISettings
  function ChangeAISettings(unitName, setting)
    return tsmod_cut_ai(TSMOD_CUT_NAME[unitName] or unitName, setting)
  end
  -- Duel: win when the opponent falls (the draft ended after 10 turns, a development placeholder).
  BattleEndCheckTable = BattleEndCheckTable or {}
  function BattleEndCheckTable.VictoryFunc(checkOnly)
    return IsBattleUnitDead("UNIT_MASTER_CH_P004")
  end
  function End_EVENT()
  end
  local lap = tsmod_cut_lap()
  local L = ({28, 50, 50})[lap]
  local drop = ({"ITEM_DROP_N204_17", "ITEM_DROP_N204_17_Lap2", "ITEM_DROP_N204_17_Lap3"})[lap]
  function ClassBattle:SpawnEnemyAndNeutralUnit_Implementation()
    tsmod_cut_spawn("UNIT_MASTER_CH_P004", "UNIT_MASTER_CH_P004", "BATTLE_UNITPARAM_CH_N404", 9, 12, CHAR_DIR_WEST, tsmod_cut_lv(L, 2), 3)
    tsmod_cut_drop("UNIT_MASTER_CH_P004", drop)
    AddChargeTimeToUnit("UNIT_MASTER_CH_P004", 20)
  end
  for _, fn in ipairs({"SetupInitialPositionAndUnit_Implementation", "SpawnEnemyAndNeutralUnit_Implementation",
      "SpawnAndChangeMapGimmick_Implementation", "PostSpawnUnit_Implementation", "PreStartBattle_Implementation"}) do
    tsmod_cut_trace(ClassBattle, fn)
  end
  tsmod_cut_trace(ClassBattleBase, "SetupInitialPositionAndUnit_Implementation")
  tsmod_cut_trace(ClassBattleBase, "SetupEventTriggers_Implementation")
  -- Test 41c: the Roselle draft never reaches setup. Log the steps before it: the C++ "setup start" trigger, the
  -- preparation start, and the map-time/weather/wind natives it calls first.
  local env = getfenv(1)
  for _, name in ipairs({"OnBattleSetupStart", "OnBattleSetupResume", "StartBattlePreparation", "GetGopBattleMapCfg",
      "SetMapTime", "SetBattleWeatherData", "SetBattleWindData", "SetWeatherType", "SetWindType"}) do
    local f = env[name]
    if type(f) == "function" then
      env[name] = function(...)
        tsmod_cut_log("call", name, ...)
        local r = {f(...)}
        tsmod_cut_log(" ret", name)
        return unpack(r)
      end
    end
  end
  if BattleSetupTemplateInstance ~= nil then
    local st = BattleSetupTemplateInstance.Start
    if type(st) == "function" then
      BattleSetupTemplateInstance.Start = function(self, ...)
        tsmod_cut_log("begin BattleSetup Start", ...)
        local r = {st(self, ...)}
        tsmod_cut_log("end BattleSetup Start")
        return unpack(r)
      end
    end
  end
  tsmod_cut_log("hooks set")
end
